package career.assistant.application.service;
import career.assistant.application.entity.*; import career.assistant.application.repository.ApplicationRepository; import career.assistant.jobscore.repository.JobScoreRepository; import org.junit.jupiter.api.Test; import java.math.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class AutoApplyWorkerServiceTest { @Test void disabledAndDryRunAreSafe(){var apps=mock(ApplicationRepository.class);var scores=mock(JobScoreRepository.class);var ex=mock(AutoApplyExecutionService.class);var el=mock(AutoApplyEligibilityService.class);assertEquals(AutoApplyWorkerService.WorkerOutcome.DISABLED,new AutoApplyWorkerService(apps,scores,ex,el,false,true,false,BigDecimal.valueOf(75)).run(true).outcome());assertEquals(AutoApplyWorkerService.WorkerOutcome.DRY_RUN_PROTECTED,new AutoApplyWorkerService(apps,scores,ex,el,true,true,false,BigDecimal.valueOf(75)).run(true).outcome());verifyNoInteractions(apps,scores,ex);}
 @Test void noEligibleApplicationsAreReported(){var apps=mock(ApplicationRepository.class);when(apps.findByStatus(ApplicationStatus.READY_TO_APPLY)).thenReturn(List.of());var s=new AutoApplyWorkerService(apps,mock(JobScoreRepository.class),mock(AutoApplyExecutionService.class),mock(AutoApplyEligibilityService.class),true,false,false,BigDecimal.valueOf(75));assertEquals(AutoApplyWorkerService.WorkerOutcome.NO_ELIGIBLE_APPLICATION,s.run(true).outcome());}
 @Test void schedulerRequiresAllFlags(){var s=new AutoApplyWorkerService(mock(ApplicationRepository.class),mock(JobScoreRepository.class),mock(AutoApplyExecutionService.class),mock(AutoApplyEligibilityService.class),true,false,true,BigDecimal.valueOf(75));assertTrue(s.schedulerAllowed());var protectedWorker=new AutoApplyWorkerService(mock(ApplicationRepository.class),mock(JobScoreRepository.class),mock(AutoApplyExecutionService.class),mock(AutoApplyEligibilityService.class),true,true,true,BigDecimal.valueOf(75));assertFalse(protectedWorker.schedulerAllowed());}
}
